fruit=banana
case $fruit in
  apple|pear) echo pome ;;
  banana)     echo berry ;;
  *)          echo unknown ;;
esac

greet() {
  local who=${1:-friend}
  echo "Hi, $who"
}
greet
greet Ana

is_even() { (( $1 % 2 == 0 )); }
is_even 4 && echo "4 is even"
is_even 7 || echo "7 is odd"

upper() { echo "$1" | tr a-z A-Z; }
shout=$(upper quiet)
echo "$shout"

cat > top404.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
log=${1:?usage: top404.sh LOGFILE [COUNT]}
n=${2:-3}
awk '$9 == 404 {print $7}' "$log" | sort | uniq -c | sort -rn | head -n "$n"
EOF
bash top404.sh access.log 2
bash top404.sh
